// ui_devkit.js
const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

module.exports = ui_devkit

async function ui_devkit (opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    icons: iconject
  }

  const { io, _ } = net(id)

  io.on = {
    up: (msg) => {
      console.log('ui_devkit:', msg.type)
    }
  }

  if (invite) io.accept(invite)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  // Constructing the exact visual layout with a dedicated close button
  shadow.innerHTML = `
    <div class="ui-devkit-container">
      <!-- Minimalist Close/Cross Button -->
      <button class="btn-close" aria-label="Close Devkit">&times;</button>

      <div class="devkit-main">
        
        <!-- Left Sidebar: Tree File Explorer -->
        <aside class="tree-explorer">
        
          <div class="explorer-tree">
            <!-- Representing the sidebar directory structure -->
            <ul class="tree-root">
              <li class="folder open"><span>cms</span></li>
              <li class="folder open"><span>config</span></li>
              <li class="folder open"><span>datasets</span></li>
              <li class="folder open"><span>components</span>
                <ul>
                  <li class="folder open"><span>playproject.io</span>
                    <ul>
                      <li class="file"><span>task.json</span></li>
                      <li class="folder"><span>config</span></li>
                      <li class="folder"><span>pins</span></li>
                    </ul>
                  </li>
                </ul>
              </li>
            </ul>
          </div>
        </aside>

        <!-- Right Workspace: 2x2 Quadrant Grid -->
        <main class="workspace-grid">
          
          <div class="quadrant dataset-editor">
            <span class="quadrant-label">dataset editor</span>
          </div>
          
          <div class="quadrant code-editor">
            <span class="quadrant-label">code editor</span>
          </div>
          
          <div class="quadrant launcher-snippet">
            <span class="quadrant-label">launcher snippet</span>
          </div>
          
          <div class="quadrant action-panel">
            <button class="btn-bookmark">
              <span>Save to bookmark</span>
              <span class="bookmark-icon"></span>
            </button>
          </div>
        </main>
      </div>
    </div>
  `

  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]

  const bookmark_icon = shadow.querySelector('.bookmark-icon')

  // Close Event: Dispatches 'close_devkit' back to ui_screen
  shadow.querySelector('.btn-close').onclick = (e) => {
    e.stopPropagation()
    _.up('close_devkit', { sid: opts.sid }, {})
  }

  // Interactive Click Handlers to propagate actions through net_helper
  shadow.querySelector('.dataset-editor').onclick = () => {
    _.up('devkit_action', { pane: 'dataset-editor' }, {})
  }

  shadow.querySelector('.code-editor').onclick = () => {
    _.up('devkit_action', { pane: 'code-editor' }, {})
  }

  shadow.querySelector('.btn-bookmark').onclick = (e) => {
    e.stopPropagation()
    _.up('save_bookmark_clicked', { sid: opts.sid }, {})
  }

  await sdb.watch(onbatch)

  return el

  async function onbatch (batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )

      const handler = on[type] || (() => {})
      handler({ data })
    }
  }

  function inject ({ data }) {
    sheet.replaceSync(data[0])
  }

  function iconject ({ data }) {
    const [bookmarkSvg = '', logoSvg = ''] = data
    if (bookmark_icon && bookmarkSvg) bookmark_icon.innerHTML = bookmarkSvg
  }
}

function fallback_module () {
  return {
    api: fallback_instance,
    _: {
      net_helper: { $: '' }
    }
  }

  function fallback_instance () {
    return {
      _: {
        net_helper: {
          0: ''
        },
        ui_devkit: {
          mapping: {
            style: 'style',
            icons: 'icons'
          }
        }
      },

      drive: {
        'icons/': {
          'bookmark.svg': { $ref: 'bookmark-outline.svg' },
        },

        'style/ui_devkit.css': {
          $ref: 'ui_devkit.css'
        }
      }
    }
  }
}